python3 - <<'PY'
import json, pathlib, sys

REQUIRED = ("id", "title", "slug", "folder", "published_date")
root = pathlib.Path("articles")
problems, seen = [], 0
for folder in sorted(p for p in root.iterdir() if p.is_dir()):
    meta = folder / "metadata.json"
    if not meta.is_file():
        problems.append(f"{folder}: no metadata.json")
        continue
    if not (folder / "article.md").is_file():
        problems.append(f"{folder}: no article.md beside metadata.json")
    try:
        record = json.loads(meta.read_text(encoding="utf-8"))
    except Exception as exc:
        problems.append(f"{meta}: not valid JSON: {exc}")
        continue
    seen += 1
    if not isinstance(record, dict):
        problems.append(f"{meta}: top level is not a JSON object")
        continue
    for key in REQUIRED:
        value = record.get(key)
        if not isinstance(value, str) or not value.strip():
            problems.append(f"{meta}: {key!r} is missing or not a non-empty string")
for line in problems:
    print(line, file=sys.stderr)
if problems:
    print(f"{len(problems)} corpus problem(s)", file=sys.stderr)
    sys.exit(1)
print(f"corpus OK: {seen} article(s), each with a parseable metadata.json and an article.md")
PY
